CREATE TABLE public.customer_quote_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL DEFAULT public.current_company_id() REFERENCES public.companies(id), storage_path text NOT NULL UNIQUE, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.customer_quote_photos TO authenticated;
GRANT ALL ON public.customer_quote_photos TO service_role;
ALTER TABLE public.customer_quote_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Company quote photo read" ON public.customer_quote_photos FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.is_company_manager() AND public.member_is_active(auth.uid()));
CREATE POLICY "Company quote photo insert" ON public.customer_quote_photos FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND created_by=auth.uid() AND storage_path=company_id::text||'/'||id::text||'.jpg' AND public.is_company_manager() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'core'));
CREATE POLICY "Unused quote photo delete" ON public.customer_quote_photos FOR DELETE TO authenticated USING(company_id=public.current_company_id() AND public.is_company_manager() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'core') AND NOT EXISTS(SELECT 1 FROM public.customer_quotes q WHERE q.company_id=customer_quote_photos.company_id AND (q.data->'photos' @> jsonb_build_array(jsonb_build_object('id',customer_quote_photos.id)) OR q.snapshot->'document'->'photos' @> jsonb_build_array(jsonb_build_object('id',customer_quote_photos.id)))));
CREATE POLICY "Private quote image read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='quote-photos' AND (storage.foldername(name))[1]=public.current_company_id()::text AND public.is_company_manager() AND public.member_is_active(auth.uid()));
CREATE POLICY "Private quote image insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='quote-photos' AND (storage.foldername(name))[1]=public.current_company_id()::text AND name ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.jpg$' AND public.is_company_manager() AND public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core'));
CREATE POLICY "Unused private quote image delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='quote-photos' AND (storage.foldername(name))[1]=public.current_company_id()::text AND public.is_company_manager() AND public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core') AND NOT EXISTS(SELECT 1 FROM public.customer_quote_photos p WHERE p.storage_path=name));
CREATE FUNCTION public.validate_customer_quote_photos() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb; BEGIN
 IF NEW.data->'photos' IS NULL THEN RETURN NEW; END IF;
 IF jsonb_typeof(NEW.data->'photos') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.data->'photos')>10 THEN RAISE EXCEPTION 'Attach up to 10 quote photos'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(NEW.data->'photos') LOOP
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR length(coalesce(p->>'caption',''))>500 OR NOT EXISTS(SELECT 1 FROM public.customer_quote_photos f JOIN storage.objects o ON o.bucket_id='quote-photos' AND o.name=f.storage_path WHERE f.id=(p->>'id')::uuid AND f.company_id=NEW.company_id) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p) k WHERE k NOT IN ('id','caption')) THEN RAISE EXCEPTION 'Quote photo unavailable or invalid'; END IF;
 END LOOP;
 RETURN NEW; END $$;
CREATE TRIGGER customer_quotes_validate_photos BEFORE INSERT OR UPDATE OF data ON public.customer_quotes FOR EACH ROW EXECUTE FUNCTION public.validate_customer_quote_photos();